new file mode 100644
index 0000000..b64c97d
--- /dev/null
+++ b/src/realtime/realtime-voice.service.spec.ts
@@ -0,0 +1,35 @@
+jest.mock('ws', () => {
+  const instances: any[] = [];
+  const Mock: any = function (this: any, url: string, opts: any) {
+    this.url = url;
+    this.opts = opts;
+    this.handlers = {};
+    this.sent = [];
+    this.on = (e: string, h: any) => (this.handlers[e] = h);
+    this.send = (m: string) => this.sent.push(m);
+    instances.push(this);
+  };
+  Mock.OPEN = 1;
+  Mock.instances = instances;
+  return { __esModule: true, default: Mock };
+});
+import WebSocket from 'ws';
+import { OPENAI_REALTIME_URL, RealtimeVoiceService } from './realtime-voice.service';
+
+describe('RealtimeVoiceService GA migration', () => {
+  it('uses GA model, no beta header, GA session and events', async () => {
+    expect(OPENAI_REALTIME_URL).toContain('model=gpt-realtime-2.1');
+    const svc = new RealtimeVoiceService('k');
+    const onAudio = jest.fn();
+    const p = svc.connectToOpenAI(onAudio);
+    const ws = (WebSocket as any).instances[0];
+    expect(ws.opts.headers['OpenAI-Beta']).toBeUndefined();
+    ws.handlers.open();
+    await p;
+    const first = JSON.parse(ws.sent[0]);
+    expect(first.session.type).toBe('realtime');
+    expect(first.session.audio.output.voice).toBe('alloy');
+    ws.handlers.message(Buffer.from(JSON.stringify({ type: 'response.output_audio.delta', delta: 'x' })));
+    expect(onAudio).toHaveBeenCalledWith('x');
+  });
+});
