+  it('calls ai.models.generateContent with systemInstruction, store=false and a non-retired default model', async () => {
+    generateContent.mockResolvedValue({ text: ' <p>hi</p> ' });
+    const cfg = { get: (k: string) => (k === 'GEMINI_API_KEY' ? 'k' : undefined) };
+    const svc = new DispatchEmailLlmService(cfg as any);
+    const r = await svc.generateEmailReport({
+      employee: { id: '1', email: 'a@b.c', fullName: 'A', profile: 'p', skills: [] },
+      project: { id: 'p', title: 't' },
+      sprints: [],
+    });
+    expect(r.html).toBe('<p>hi</p>');
+    const arg = generateContent.mock.calls[0][0];
+    expect(arg.model).toBe('gemini-2.5-flash-lite');
+    expect(arg.config.systemInstruction).toBeDefined();
+    expect(arg.config.httpOptions.extraBody).toEqual({ store: false });
+  });
+});
