new file mode 100644
index 0000000..fe6ffa2
--- /dev/null
+++ b/src/auth/google-auth-lib.spec.ts
@@ -0,0 +1,16 @@
+import * as fs from 'fs';
+import { OAuth2Client } from 'google-auth-library';
+
+describe('google-auth-library 11', () => {
+  it('is v11 with Node 22 declared', () => {
+    const v = JSON.parse(fs.readFileSync('node_modules/google-auth-library/package.json', 'utf8')).version;
+    expect(v.startsWith('11.')).toBe(true);
+    const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
+    expect(pkg.engines.node).toBe('>=22');
+    expect(fs.readFileSync('Dockerfile', 'utf8')).not.toMatch(/node:20/);
+  });
+  it('verifyIdToken is still available', () => {
+    const c = new OAuth2Client('id');
+    expect(typeof c.verifyIdToken).toBe('function');
+  });
+});

